action.command:
cd /workspace && python - << 'PY'
from pathlib import Path
exp_lines = Path('expected.md').read_text(encoding='utf-8').splitlines()
new_line = None
for line in exp_lines:
    if line.startswith('**Random effects (Groups)**'):
        new_line = line
        break
if new_line is None:
    raise SystemExit('Could not find random-effects line in expected.md')

script_path = Path('repro_pythonic_table_3.sh')
script_lines = script_path.read_text(encoding='utf-8').splitlines()
out_lines = []
for line in script_lines:
    if 'Random effects (Groups)' in line:
        out_lines.append(new_line)
    else:
        out_lines.append(line)
script_path.write_text('\n'.join(out_lines) + '\n', encoding='utf-8')
PY

